<?php
require_once 'functions.php'; require_login(); $me=(int)$_SESSION['user_id']; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $to=(int)($_POST['recipient_id']??0); $message=trim($_POST['message']??'');
 if($to===$me || $to<1 || $message==='' || mb_strlen($message)>2000){$error='Vérifie le destinataire et le message (2 000 caractères maximum).';}
 else { $q=$pdo->prepare('SELECT id FROM users WHERE id=?');$q->execute([$to]); if(!$q->fetch()) $error='Ce compte n’existe pas.'; else { $q=$pdo->prepare('INSERT INTO private_messages(sender_id,recipient_id,message) VALUES(?,?,?)');$q->execute([$me,$to,$message]);$q=$pdo->prepare('INSERT INTO notifications(user_id,content,target_url) VALUES(?,?,?)');$q->execute([$to,'Tu as reçu un nouveau message.','messages.php?with='.$me]);header('Location: messages.php?with='.$to);exit; } }
}
$users=$pdo->prepare('SELECT DISTINCT u.id,u.username FROM users u JOIN private_messages m ON (m.sender_id=u.id AND m.recipient_id=?) OR (m.recipient_id=u.id AND m.sender_id=?) WHERE u.id<>? ORDER BY u.username');$users->execute([$me,$me,$me]);$contacts=$users->fetchAll();$with=(int)($_GET['with']??($contacts[0]['id']??0));$person=null;$msgs=[];
if($with && $with!==$me){$q=$pdo->prepare('SELECT id,username FROM users WHERE id=?');$q->execute([$with]);$person=$q->fetch();if($person){$q=$pdo->prepare('SELECT m.*,s.username AS sender_name FROM private_messages m JOIN users s ON s.id=m.sender_id WHERE (sender_id=? AND recipient_id=?) OR (sender_id=? AND recipient_id=?) ORDER BY created_at ASC LIMIT 200');$q->execute([$me,$with,$with,$me]);$msgs=$q->fetchAll();}}
$all=$pdo->prepare('SELECT id,username FROM users WHERE id<>? ORDER BY username');$all->execute([$me]);$allUsers=$all->fetchAll();page_header('Messages'); ?>
<section class="page-intro"><div class="eyebrow">EN PRIVÉ</div><h1>Messages</h1><p>Échange avec les autres membres de Sonora.</p></section>
<?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?><div class="message-layout"><aside class="panel"><h3>Conversations</h3><?php foreach($contacts as $u): ?><p><a href="messages.php?with=<?= (int)$u['id'] ?>"><?= e($u['username']) ?></a></p><?php endforeach; ?><hr><h3>Nouveau message</h3><form method="post"><label>Destinataire<select name="recipient_id" required><?php foreach($allUsers as $u): ?><option value="<?= (int)$u['id'] ?>" <?= $with===(int)$u['id']?'selected':'' ?>><?= e($u['username']) ?></option><?php endforeach; ?></select></label><label>Message<textarea name="message" maxlength="2000" required></textarea></label><button class="button" type="submit">Envoyer</button></form></aside><section class="panel"><h2><?= $person?e($person['username']):'Choisis une conversation' ?></h2><div class="chat-log"><?php foreach($msgs as $m): ?><div class="chat-line <?= (int)$m['sender_id']===$me?'mine':'' ?>"><strong><?= e($m['sender_name']) ?></strong><p><?= nl2br(e($m['message'])) ?></p><small><?= e(date('d/m H:i',strtotime($m['created_at']))) ?></small></div><?php endforeach; ?><?php if($person && !$msgs): ?><p>La conversation commence ici.</p><?php endif; ?></div><?php if($person): ?><form method="post"><input type="hidden" name="recipient_id" value="<?= (int)$person['id'] ?>"><label>Ton message<textarea name="message" maxlength="2000" required></textarea></label><button class="button" type="submit">Envoyer le message</button></form><?php endif; ?></section></div><?php page_footer(); ?>